package com.aviatortrends.analyzer;
import android.content.*; import org.json.*; import java.util.*;
public class ResultStore { private final SharedPreferences p; public ResultStore(Context c){p=c.getSharedPreferences("history",0);} public synchronized List<Result> all(){List<Result> out=new ArrayList<>();try{JSONArray a=new JSONArray(p.getString("results","[]"));for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);out.add(new Result(o.getLong("id"),o.getDouble("m"),o.getLong("t"),o.optString("s","manual"),(float)o.optDouble("c",1)));}}catch(Exception ignored){}out.sort((a,b)->Long.compare(b.timestamp,a.timestamp));return out;} public synchronized boolean add(double m,String s,float c){if(m<1||m>100000)return false;long now=System.currentTimeMillis();List<Result> r=all();if(!r.isEmpty()&&"ocr".equals(s)&&Math.abs(r.get(0).multiplier-m)<.0001&&now-r.get(0).timestamp<2500)return false;r.add(new Result(now,m,now,s,c));save(r);return true;} public synchronized void clear(){p.edit().remove("results").apply();}private void save(List<Result> r){JSONArray a=new JSONArray();try{for(Result x:r){JSONObject o=new JSONObject();o.put("id",x.id);o.put("m",x.multiplier);o.put("t",x.timestamp);o.put("s",x.source);o.put("c",x.confidence);a.put(o);}}catch(Exception ignored){}p.edit().putString("results",a.toString()).apply();} public synchronized String csv(){StringBuilder b=new StringBuilder("id,multiplier,timestamp,source,confidence\n");for(Result x:all())b.append(x.id).append(',').append(x.multiplier).append(',').append(x.timestamp).append(',').append(x.source).append(',').append(x.confidence).append('\n');return b.toString();}}
